package com.aadil.ecommerce.entities;import jakarta.persistence.*;import lombok.Data;import java.time.LocalDateTime;@Entity@Table (name = "AdminInvitation")@Datapublic class AdminInvitationEntity {    @GeneratedValue (strategy = GenerationType.IDENTITY)    @Id    private Long id;    @Column(nullable = false)    private String name;    @Column(nullable = false)    private String email;    @Column (nullable = false,updatable = false)    private String tokenHash;    @Column (nullable = false)    private LocalDateTime expiresAt;    @Column(nullable = false)    private boolean isUsed;    @Column (nullable = false)    private LocalDateTime createdAt;    @PrePersist    protected void onCreate (){        this.createdAt = LocalDateTime.now();    }}